const input = $input.first().json;
const s = (value) => String(value ?? '').trim();
const lower = (value) => s(value).toLowerCase();

const title = s(input.action_title);
const goal = s(input.business_goal);
const action = s(input.proposed_action);
const systems = s(input.systems_touched);
const dataClass = s(input.data_classification) || 'unspecified';
const destination = s(input.destination_boundary) || 'unspecified';
const sideEffects = s(input.expected_side_effects) || 'unspecified';
const impact = s(input.customer_impact) || 'unspecified';
const posture = lower(input.policy_posture) || 'standard';
const reversibleText = lower(input.reversible) || 'unknown';
let risk = Number(input.risk_level ?? 0);
if (!Number.isFinite(risk)) risk = 0;
risk = Math.max(0, Math.min(100, Math.round(risk)));

const combined = [action, systems, dataClass, destination, sideEffects, impact].join(' ').toLowerCase();
const writeWords = ['send', 'publish', 'update', 'refund', 'delete', 'export', 'sync', 'write', 'notify', 'post', 'create'];
const dataWords = ['customer', 'personal', 'pii', 'account', 'payment', 'support', 'ticket', 'order', 'email'];
const externalWords = ['external', 'public', 'customer', 'vendor', 'partner', 'slack', 'email', 'webhook', 'api'];

const hasSideEffect = writeWords.some((word) => combined.includes(word)) || sideEffects !== 'unspecified';
const touchesSensitiveData = dataWords.some((word) => combined.includes(word));
const crossesBoundary = externalWords.some((word) => destination.toLowerCase().includes(word));
const reversible = ['true', 'yes', 'y', '1'].includes(reversibleText);

const blockers = [];
const warnings = [];
if (!title) blockers.push('missing action title');
if (!goal) blockers.push('missing business goal');
if (!action) blockers.push('missing proposed action');
if (!systems) blockers.push('missing systems touched');
if (dataClass === 'unspecified') warnings.push('data classification was not provided');
if (destination === 'unspecified') warnings.push('destination/boundary was not provided');

let exposureLevel = 'low';
if (risk >= 70 || (touchesSensitiveData && hasSideEffect && !reversible)) exposureLevel = 'high';
else if (risk >= 40 || touchesSensitiveData || hasSideEffect || crossesBoundary) exposureLevel = 'medium';

let recommendedControl = 'log_only';
if (blockers.length) recommendedControl = 'fix_intake';
else if (exposureLevel === 'high' || ['strict', 'regulated', 'approval-first'].includes(posture)) recommendedControl = 'require_approval';
else if (exposureLevel === 'medium') recommendedControl = 'review_or_approve';

const blastRadius = [];
if (touchesSensitiveData) blastRadius.push('customer/support data');
if (hasSideEffect) blastRadius.push('operational side effects');
if (crossesBoundary) blastRadius.push('external or cross-system boundary');
if (!blastRadius.length) blastRadius.push('read-only or internal analysis');

const usable = blockers.length === 0;
const preflightEnvelope = {
  requester: s(input.requester) || 'unspecified',
  policy_posture: posture,
  approval_channel: s(input.approval_channel) || 'unspecified',
  data_classification: dataClass,
  destination_boundary: destination,
  expected_side_effects: sideEffects,
  customer_impact: impact,
  normalized_risk: risk,
  reversible,
  touches_sensitive_data: touchesSensitiveData,
  has_side_effect: hasSideEffect,
  crosses_boundary: crossesBoundary,
  exposure_level: exposureLevel,
  recommended_control: recommendedControl,
  blast_radius: blastRadius,
  warnings,
  blockers,
};
const preflightSummary = `usable=${usable}; normalized_risk=${risk}; exposure_level=${exposureLevel}; recommended_control=${recommendedControl}; data_classification=${dataClass}; destination_boundary=${destination}; side_effects=${sideEffects}; blast_radius=${blastRadius.join(', ')}; warnings=${warnings.join('; ') || 'none'}; blockers=${blockers.join('; ') || 'none'}`;

return [{
  json: {
    ...input,
    usable,
    normalized_risk: risk,
    exposure_level: exposureLevel,
    recommended_control: recommendedControl,
    blast_radius: blastRadius.join(', '),
    warnings: warnings.join('; ') || 'none',
    blockers: blockers.join('; ') || 'none',
    preflight_summary: preflightSummary,
    preflight_envelope: preflightEnvelope,
    preflight_envelope_json: JSON.stringify(preflightEnvelope, null, 2),
  },
}];
